INSERT INTO `grupa_faktora_rizika` (`id`, `naziv`, `opis`) VALUES (2,'Rizik klijenta','Rizik vezan za karakteristike klijenta');
INSERT INTO `grupa_faktora_rizika` (`id`, `naziv`, `opis`) VALUES (3,'Rizik transakcije','Rizik vezan za transakcije klijenta');
INSERT INTO `grupa_faktora_rizika` (`id`, `naziv`, `opis`) VALUES (4,'Rizik proizvoda ili usluge','Rizik vezan za proizvode ili usluge');
INSERT INTO `grupa_faktora_rizika` (`id`, `naziv`, `opis`) VALUES (5,'Rizik distributivnog kanala','Rizik vezan za kanal distribucije');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (1,1,'Visokorizične treće države (FATF lista)','Visokorizične treće države koje u skladu sa Zakonom objavljuje FOJ - države koje su od strane FATF označene kao države koje ne primijenjuju adekvatne mere za sprečavanje pranja novca i finansiranja terorizma.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (2,1,'Off shore pravna lica','Off shore pravna lica (obveznik je dužan da detaljno izvrši procjenu poslovanja firme koja dolazi sa off shore destinacija. Naime, često se mogu pojaviti „školjka firme“ koje su prikrivene i svoje namjere skrivaju pod legalnom djelatnošću.)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (3,1,'Države koje podržavaju ili finansiraju terorizam','Države koje su od strane kredibilnih institucija (FATF, UN i dr) označene kao države koje podržavaju ili finansiraju terorističke aktivnosti ili organizacije');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (4,1,'Države sa visokim stepenom korupcije i kriminala','Države koje su od strane kredibilnih institucija (npr. Svjetska banka, MMF) označene kao države sa visokim stepenom korupcije i kriminala');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (5,2,'Izbjegavanje ličnog pojavljivanja','Klijent prilikom uspostavljanja poslovnog odnosa sa obveznikom izbjegava lično pojavljivanje, već umjesto toga insistira na posrednom kontaktu');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (6,2,'Nejasna vlasnička struktura','Klijenti čija je struktura takva da je teško utvrditi stvarnog vlasnika ili lica koje ima kontrolni udio, klijenti u čijoj su strukturi prepoznati trastovi, klijenti koji koriste treća lica, klijenti kod kojih je zbog strukture, pravne forme ili složenih i nejasnih odnosa, teško utvrditi identitet njihovih stvarnih vlasnika ili lica koja njima upravljaju, kao što su: fondacije, trastovi i druga slična lica stranog prava, dobrotvorne i neprofitne nevladine organizacije: pravna lica sa nejasnom vlasničkom strukturom i koja nije osnovala kompanija iz zemlje koja primijenjuje standarde u oblasti sprečavanja pranja novca i finansiranja terorizma koji su na nivou standarda propisanih Zakonom');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (7,2,'Djelatnost sa velikim prometom gotovine','Klijent se bavi djelatnošću koja uključuje veliki promet gotovine (na primjer: restoran, kladionica, pumpa, mjenjačnica, kazino, cvjećara, trgovac plemenitim metalima, automobilima, umjetninama, prevoznik robe i putnika, sportsko društvo, građevinska firma, investitor u izgradnju nekretnina...)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (8,2,'Računi kod više finansijskih institucija bez opravdanja','Klijenti koji imaju račune kod različitih finansijskih institucija na istom području bez evidentne ekonomske opravdanosti');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (9,2,'Zahtjev za neopravdano brzim obavljanjem posla','Klijent koji bez značajnog razloga zahtijeva brzo obavljanje posla ili transakcije, pritom ne vodeći računa o većim troškovima koje to iziskuje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (10,2,'Nuđenje novca ili poklona kao protivusluge','Klijent nudi novac, poklone ili druge pogodnosti kao protivuslugu za poslove za koje postoji sumnja da nisu u potpunosti u skladu sa propisima');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (11,2,'Uvjeravanje obveznika da dokumentacija nije potrebna','Klijent želi da uvjeri obveznika da nije potrebno da popuni ili priloži neki od potrebnih dokumenata');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (12,2,'Izbjegavanje dostavljanja dokumentacije','Klijent izbjegava dostavljanje neophodne dokumentacije ili obveznik gaji sumnju u vjerodostojnost pribavljenje dokumentacije');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (13,2,'Visokorizična djelatnost prema Nacionalnoj procjeni rizika','Klijent obavlja djelatnost koja je u skladu sa Nacionalnom procjenom rizika označena kao visokorizična');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (14,2,'Nesrazmjer zaposlenih i prostora sa obimom poslovanja','Klijent nema zaposlenih, niti poslovne prostorije, što nije srazmjerno sa obimom poslovanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (15,2,'Česte promjene naziva, sjedišta i vlasničke strukture','Klijent vrši česte promjene naziva, sjedišta, vlasničke stukture, statusne promjene');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (16,2,'Neuobičajen zahtjev za zaštitom privatnosti','Klijent iskazuje neuobičajen zahtev za zaštitom privatnosti, posebno u vezi s podacima koji se odnose na njegov identitet, djelatnost, imovinu ili poslovanje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (17,2,'Odustajanje od naloga radi izbjegavanja identifikacije','Klijent odustaje od naloga radi izbjegavanja identifikacije nakon što je u sklad sa odredbama zakona upoznat sa obavezom da se identifikuje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (18,2,'Povezanost sa licima pod restriktivnim mjerama','Klijenti kod kojih postoji sumnja da je lice označeno na restriktivnim mjerama (konsolidovana lista Komiteta za sankcije na osnovu Rezolucije 1267 Savjeta bezbjednosti Ujedinjenih nacija, „crne liste“ EU i druge) ili da je lice povezano sa licima koja se nalaze na restriktivnim mjerama');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (19,2,'Politički eksponirano lice (PEL)','Klijent koji je PEL');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (20,2,'Česta promjena ovlašćenog revizora','Klijent, obveznik revizije, svake godine zaključuje ugovor sa novim ovlašćenim revizorom');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (21,2,'Uvjeravanje računovođe da dokumentacija nije potrebna','Klijent želi da uvjeri računovođu da nije potrebno da popuni ili priloži neki od potrebnih dokumenata ili mu nije poznato gdje se čuva poslovna dokumentacija');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (22,2,'Sporne ili nepotpune računovodstvene isprave','Klijent ne dostavlja računovodstvenu ispravu ili postoji sumnja u vjerodostojnost računovodstvene isprave da je istinita i da prikazuje poslovnu promjenu ili dostavljena računovodstvena isprava ne sadrži sve podatke potrebne za knjiženje u poslovnim knjigama, a klijent i dalje insistira da takva isprava bude proknjižena');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (23,2,'Identifikacija kopijama ili neličnim ispravama','Klijent prilaže samo kopije ličnih isprava ili pokušava da obavi identifikaciju sa drugim ispravama, koje nijesu lične isprave');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (24,2,'Zahtjev da računovođa obavi transakciju u svoje ime','Klijent u suprotnosti sa poslovnom praksom traži da računovođa u svoje ime i za svoj račun obavi transakciju');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (25,2,'Raskid ugovora sa računovođom zbog zahtjeva za objašnjenjem','Kijent raskida ugovor o saradnji sa računovođom zbog zahtjeva za dodatnim objašnjenjem realizacije (ili najave realizacije) određenih transakcija');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (26,2,'Česta promjena računovođe','Klijent često mijenja računovođe');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (27,2,'Fakturisanje neizvršenih usluga i plaćanja ka ofšor destinacijama','Klijent fakturiše usluge za koje se ne može sa sigurnošću potvrditi da su izvršene, odnosno vrši plaćanja za određenu vrstu usluge pravnim licima sa sjedištem na ofšor destinacijama, odnosno \"poreskim rajevima\"');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (28,2,'Nepoznavanje ili nezainteresovanost za sopstveno poslovanje','Odgovorno lice klijenta ne poznaje dobro svoje poslovanje ili je vidno nezainteresovano za poslovanje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (29,2,'Neočekivano interesovanje za kontrole SPNFT','Klijent neočekivano pokazuje veliko interesovanje za kontrole i politike njihovog sprovođenja, dobro poznaje pravila o obavještavanju o sumnjivim transakcijama i djeluje kao da je dobro upoznat sa predmetima koji se odnose na pranje novca i finansiranje terorizma');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (30,2,'Upravljanje klijentom putem neformalnih kanala','Klijentom se upravlja putem neformalnih kanala (npr. putem porodičnih ili prijateljskih odnosa)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (31,2,'Poslovanje u neuobičajenim okolnostima','Klijent svoje poslovne odnose ili transakcije obavlja (ili je obavljao) u neuobičajenim okolnostima, kao na primjer: velika i neočekivana geografska udaljenost između klijenta i obveznika sa kojim je uspostavljen poslovni odnos ili vršena transakcija; često, neočekivano i ekonomski neopravdano uspostavljanje poslovnih odnosa slične vrste sa više obveznika, kao što je otvaranje računa kod većeg broja obveznika, zaključivanje više ugovora o pružanju usluga u kratkom periodu');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (32,2,'Iznenadna aktivacija neaktivnih računa','Klijentovi neaktivni računi iznenada postaju aktivni i preko njih se vrše značajni transferi po obimu i učestalosti u odnosu na klijentov obim poslovanja.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (33,2,'Nabavka robe van predmeta poslovanja ili po višim cijenama','Nabavka robe ili usluga koje nikada nisu bile predmet poslovanja stranke ili nabavka robe po višim cijenama od tržišnih bez jasnih razloga za takvu nabavku');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (34,2,'Insistiranje na tajnosti transakcije','Insistiranje na tajnosti transakcije.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (35,2,'Kupovina neviđene nekretnine preko posrednika','Klijent koji se interesuje za nekretninu, koju nije lično vidio, tu nekretninu kupuje preko posrednika (advokata, zastupnika, bliskih osoba i dr.), a postoje saznanja da klijent kupac obavlja razna poslovanja na ivici legalnosti (nezakonito)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (36,2,'Nelogični odgovori o načinu plaćanja nepokretnosti','Vrijednost ponuđene nepokretnosti je velika, a klijent daje nelogične odgovore o načinima plaćanja te nepokretnosti, odnosno raspituje se da se transakcije isključivo obave u gotovom novcu ili kombinovano sa nepouzdanim izvorima plaćanja.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (37,2,'Loša reputacija i korišćenje alternativnih kanala plaćanja','Postoje saznanja da klijent ima lošu reputaciju ili da postoji sumnja u izvore sredstava, da u svom poslovanju koristi virtuelne valute (npr. bitkoin ili lajtkoin) ili koristi alternativne kanale plaćanja (npr. havala, hundi), sa ciljem izbjegavanja redovnih finansijskih kanala');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (38,2,'Izvori novca u inostranstvu i plaćanja u više manjih iznosa','Klijent koji prema saznanjima ima izvore novca u inostranstvu ili van finansijskog sistema i želi da ugovori plaćanja u više manjih iznosa koristeći platne institucije za prenos novca.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (39,2,'Insistiranje na novim uslugama novčanog poslovanja','Klijent insistira na novim uslugama novčanog poslovanja, pri čemu postoji vjerovatnoća da ne mogu da se identifikuju realni tokovi novca ili učesnici plaćanja koji se do sada nijesu pojavljivali na tržištu kod posrednika ili se koriste različiti elektronski ili drugi kanali plaćanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (40,3,'Odstupanje od standardnog ponašanja klijenta','Transakcije koje znatno odudaraju od standardnog ponašanja klijenta');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (41,3,'Transakcije bez ekonomske opravdanosti','Transakcije kod kojih ne postoji ekonomska opravdanost (tipičan primjer predstavlja tzv. trgovanje hartijama od vrijednosti sa planiranim gubitkom - učestala kupovina hartija od vrijednosti koje se kupuju uplatom gotovine na namjenske račune, nakon se čega ubrzo prodaju ispod cijene; kod ovakvih transakcija evidentna je namjera klijenta da se u što kraćem roku oslobodi kupljenih hartija od vrijednosti, pritom ne mareći za iznos po kojoj iste prodaje)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (42,3,'Izbjegavanje standardnih metoda kontrole','Transakcije koje se vrše tako da se izbegavaju standardni i uobičajeni Metodi kontrole');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (43,3,'Odbijanje dostavljanja prateće dokumentacije','Transakcije kod kojih klijent odbija da dostavi prateću dokumentaciju');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (44,3,'Povezane transakcije ispod limita za izvještavanje','Transakcije koje su međusobno povezane a obavljaju se u kraćem vremenskom periodu ili u više intervala međusobno, a koje su u iznosu ispod limita za izvještavanje FOJ-a, U iznosu od 100.000,00 eura)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (45,3,'Više učesnika bez pravnog osnova i ekonomske opravdanosti','Transakcije koje obuhvataju više učesnika koji obavljaju transakciju bez jasnog pravnog osnova i ekonomske opravdanosti');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (46,3,'Dokumentacija ne odgovara načinu sprovođenja transakcije','Transakcije kod kojih dokumentacija ne odgovara načinu sprovođenja same transakcije');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (47,3,'Nejasan izvor sredstava','Transakcije kod kojih izvor sredstava nije jasan ili se ne može utvrditi njihova veza s poslovanjem klijenta');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (48,3,'Najavljene blok transakcije akcijama','Najavljene blok transakcije akcijama, a naročito kada se kao kupci pojavljuju novoosnovane kompanije ili kompanije registrovane na off shore destinacijama');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (49,3,'Neobjašnjive fluktuacije u bilansu uspjeha','Neobjašnjive fluktuacije u bilansu uspeha – neusklađenost bilansnih pozicija (neopravdano visoki prihodi u odnosu na rashode)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (50,3,'Fakturisanje usluga upitne izvršenosti','Transakcije kod kojih se fakturiše usluga za koju se ne može sa sigurnošću utvrditi da li je zaista izvršena');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (51,3,'Učestale transakcije u velikim iznosima','Učestale transakcije u velikim iznosima koje nisu u skladu sa redovnim poslovanjem (na primjer, kod procjene rizika transakcije treba poći od odgovora na sledeća pitanja: Šta je predmet transakcije? Da li je transakcija neobično visoka uzimajući u obzir dotadašnje transakcije konkretnog klijenta? Da li su podaci u prezentovanoj dokumentaciji revizoru usaglašeni? Da li uknjiženja promjena u finansijskim izvještajima vršena na osnovu vjerodostojnih dokumenata?).');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (52,3,'Transakcije koje omogućavaju anonimnost','Transakcije koje omogućavaju anonimnost ili prikrivanje identiteta korisnika, kao što su prepaid kartice, virtuelne valute, fiducijarni računi ili proizvodi bez obavezne identifikacije korisnika');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (53,3,'Usitnjavanje transakcija putem elektronskih kanala (smurfing)','Upotreba mobilnih i elektronskih kanala za učestale transakcije u malim iznosima koje ukupno dostižu prag za izvještavanje, što može ukazivati na tzv. smurfing ili fragmentaciju iznosa radi prikrivanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (54,3,'Preprodaja nepokretnosti po višestruko većoj cijeni','Klijent koji je nedavno kupio nepokretnost, prodaje je za višestruko veću cijenu od kupovne, što ukazuje na povezana lica zbog fiktivnog transfera novca I skrivanja porijekla i raslojavanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (55,3,'Kupovina nekretnina od strane nepoznatih ili off shore kompanija','Ugovorene kupovine nekretnina, a naročito kada se kao kupci pojavljuju nepoznate ili novonosnovane kompanije, a posebno one koje dolaze sa off shore destinacija');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (56,3,'Kupovina nekretnina sredstvima sa više računa','Kupovina nekretnina koja se obavlja sredstvima uplaćenim na više računa u različitim bankama, a naročito ako su deponovana sredstva u iznosu nešto ispod iznosa za izvještavanje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (57,3,'Kupovina neviđene nekretnine preko posrednika','Klijent koji se interesuje za nekretninu, koju nije lično vidio, tu nekretninu kupuje preko posrednika (advokata, zastupnika, bliskih osoba i dr.), a postoje saznanja da klijent kupac obavlja razna poslovanja na ivici legalnosti (nezakonito)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (58,3,'Nelogični odgovori o načinu plaćanja nepokretnosti','Vrijednost ponuđene nepokretnosti je velika, a klijent daje nelogične odgovore o načinima plaćanja te nepokretnosti, odnosno raspituje se da se transakcije isključivo obave u gotovom novcu ili kombinovano sa nepouzdanim izvorima plaćanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (59,3,'Osnivanje velikog broja povezanih lica bez ekonomskog razloga','Klijent osniva, bez opravdanog razloga, veliki broj povezanih lica koja iznenada počinju da međusobno posluju bez posebno bitnih ekonomskih razloga');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (60,3,'Raspodjela dobiti iz fiktivnog poslovanja','Raspodjela neraspoređene dobiti nastale na osnovu fiktivnog poslovanja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (61,3,'Složena vlasnička struktura i prilivi od off shore kompanija','Klijent ima složenu vlasničku strukturu u dnosu na djelatnost koju obavlja, dok takođe postoje sumnje da se radi o fiktivnim transakcijama, kao i da klijent ostvaruje velike prilive od off shore kompanija, za koje je teško identifikovati vlasničku strukturu. Takođe, klijent svake godine zaključuje ugovor sa različitim privrednim društvima za reviziju.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (62,3,'Izbjegavanje ličnog pojavljivanja pri uspostavljanju odnosa','Prilikom uspostavljanja poslovnog odnosa, klijent je izbjegavao lično pojavljivanje, insistirajući na posrednom kontaktu.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (63,4,'Proizvodi koji omogućavaju anonimnost','Proizvodi i usluge koji omogućavaju anonimnost ili prikrivanje identiteta korisnika, kao što su prepaid kartice, virtuelne valute, fiducijarni računi ili proizvodi bez obavezne identifikacije korisnika');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (64,4,'Brzo i neselektivno preusmjeravanje sredstava','Proizvodi i usluge koje omogućavaju brzo i neselektivno preusmjeravanje sredstava, naročito kroz mehanizme kao što su elektronski transferi bez dovoljne kontrole ili korišćenje platnih instrumenata trećih lica');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (65,4,'Visoke gotovinske transakcije','Proizvodi i usluge koji podrazumijevaju visoke gotovinske transakcije, naročito oni koji omogućavaju polaganje, isplatu ili konverziju značajnih iznosa u gotovini bez proporcionalne kontrole (npr. mjenjačnice, gotovinske blagajne)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (66,4,'Lako prenosivi ili konvertibilni proizvodi','Proizvodi koji se mogu lako prenijeti ili konvertovati, kao što su dragocjeni metali, vrijednosni papiri na donosioca, luksuzna roba visoke vrijednosti (npr. satovi, umjetnine), i koji omogućavaju brzo raslojavanje sredstava');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (67,4,'Kompleksne finansijske usluge','Kompleksne finansijske usluge koje uključuju sofisticirane strukture ili višestruka posredovanja, kao što su trustovi, off shore fondovi, derivativni proizvodi i razne forme strukturiranih investicija');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (68,4,'Višestruko plaćanje iz različitih izvora','Proizvodi koji omogućavaju ili podstiču višestruko plaćanje iz različitih izvora, posebno ako nije obavezno identifikovati sve izvore finansiranja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (69,4,'Česti povrati sredstava i raskidi ugovora','Usluge koje uključuju česte povrate sredstava, raskide ugovora, ili preusmjeravanje uplata, naročito kada klijent ne pruža zadovoljavajuće objašnjenje za takvo ponašanje');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (70,4,'Prodaja imovine visoke vrijednosti preko posrednika','Usluge koje uključuju prodaju nepokretnosti ili pokretne imovine visoke vrijednosti, naročito kada se transakcije obavljaju preko zastupnika, fiducijarnih lica ili nerezidentnih subjekata');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (71,4,'Usluge bez fizičkog prisustva klijenta','Proizvodi i usluge koji se nude bez fizičkog prisustva klijenta, odnosno oni kod kojih se cijeli proces – od ugovaranja do plaćanja – odvija elektronski i bez lične provjere');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (72,4,'Usluge povezane sa visokorizičnim jurisdikcijama','Finansijske usluge koje uključuju visoko rizične jurisdikcije, naročito one koje su na listama nekooperativnih zemalja prema FATF, EU ili drugim relevantnim tijelima');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (73,4,'Proizvodi subjektivno određene vrijednosti','Proizvodi čija se vrijednost određuje subjektivno ili čiji je tržišni mehanizam slabije regulisan, što omogućava manipulaciju cijenama radi prikrivanja porijekla sredstava (npr. prodaja umetničkih djela, kolekcionarskih predmeta, kripto imovine)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (74,4,'Indirektno vlasništvo nad predmetima velike vrijednosti','Usluge koje omogućavaju indirektno vlasništvo nad predmetima velike vrijednosti, posebno u situacijama kada vlasništvo nije transparentno dokumentovano');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (75,4,'Usluge u zatvorenim poslovnim mrežama','Usluge koje se pružaju u okviru zatvorenih poslovnih mreža ili partnerstava, u kojima postoji niska transparentnost i minimalna eksternalna kontrola ili revizija.');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (76,5,'Uspostavljanje odnosa bez fizičkog prisustva i autentifikacije','Kanali distribucije koji omogućavaju uspostavljanje poslovnog odnosa bez fizičkog prisustva klijenta, a bez dodatnih mjera autentifikacije ili elektronske identifikacije (npr. registracija putem interneta bez video identifikacije ili kvalifikovanog elektronskog potpisa)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (77,5,'Posrednički kanali bez jasnog mandata','Posrednički kanali kroz koje klijent ne dolazi u direktan kontakt sa prodavcem ili pružaocem usluge, već koristi usluge zastupnika, advokata, notara, agenata ili fiducijarnih lica bez jasnog mandata ili ovlašćenja');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (78,5,'Korišćenje trećih lica za prenos sredstava','Korišćenje trećih lica za prenos sredstava ili imovine, naročito kada su ta treća lica registrovana u jurisdikcijama visokog rizika ili kada nije moguće pouzdano utvrditi njihov identitet i svrhu uključenosti');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (79,5,'Digitalne platforme bez adekvatne identifikacije','Distribucija proizvoda i usluga preko digitalnih platformi koje nemaju adekvatne bezbjednosne i identifikacione protokole, ili kada je omogućena registracija sa minimalnim podacima (npr. bez potvrde prebivališta ili izvora sredstava)');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (80,5,'Agenti i partneri van internih SPNFT pravila','Kanali distribucije koji uključuju agente, partnerske firme ili treća lica koje nisu obuhvaćene istim internim SPNFT pravilima, niti su podložne nezavisnoj reviziji ili regulatornom nadzoru');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (81,5,'Brzo izvršenje bez verifikacije','Kanali distribucije koji omogućavaju visoku brzinu izvršenja bez vremenskog perioda za verifikaciju transakcije, naročito u kombinaciji sa nedostatkom prethodne provjere klijenta');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (82,5,'Međunarodni ili neregulisani platni procesori','Distribucija usluga preko međunarodnih ili neregulisanih platnih procesora, koji omogućavaju transakcije bez detaljnog uvida u tokove novca i krajnjeg korisnika sredstava');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (83,5,'Neelektronski kanali bez potvrde identiteta','Korišćenje poštanskih, kurirskih ili drugih neelektronskih oblika komunikacije za zaključenje ugovora, distribuciju proizvoda i usluga, i realizaciju transakcija, bez mogućnosti potvrde identiteta ili autentičnosti dostavljene dokumentacije');
INSERT INTO `indikator_rizika` (`id`, `grupa_faktora_rizika_id`, `naziv`, `opis`) VALUES (84,5,'Povremeni i jednokratni kanali distribucije','Kanali distribucije koji se koriste povremeno i jednokratno, bez postojanja trajnog poslovnog odnosa, posebno kada nije moguće pratiti istoriju komunikacije ili transakcija.');
